INSERT INTO public.edition (id, title, description, theme, category, author, "coverImage", "estimatedTime", status, date, snapshot, "createdAt", "updatedAt") VALUES ('cmvj6ym80000008jp3qe0gmty', 'Statue', 'Do you know the statues of the world?', 'ThemeKEY', 'category', 'Bhumi', NULL, '10', 'SCHEDULED', '2026-10-22', '{"id": "cmvj6ym80000008jp3qe0gmty", "nodes": [{"id": "cmvj6audc000108jm2y9tihzw", "type": "image-select", "mapTitle": "Statues of the World", "isPremium": false, "subStages": [{"id": "cmvj6audc000108jm2y9tihzw-1", "type": "image-select", "points": 1, "options": [{"id": "opt-1", "image": "img/1bd22ad935fb-statue-of-unity.webp", "label": "Statue of Unity", "feedback": "Correct! The Statue of Unity depicts Sardar Vallabhbhai Patel.", "isCorrect": true}, {"id": "opt-2", "image": "img/cf8561f9c513-spring-temple-buddha.webp", "label": "Spring Temple Buddha", "feedback": "Not quite! The Spring Temple Buddha was the world''s tallest statue before 2018.", "isCorrect": false}, {"id": "opt-3", "image": "img/1e83cf08d575-laykyun-sekkya.webp", "label": "Laykyun Sekkya", "feedback": "Not quite! Laykyun Sekkya is a giant standing Buddha statue in Myanmar.", "isCorrect": false}, {"id": "opt-4", "image": "img/9852baea9657-ushiku-daibutsu.webp", "label": "Ushiku Daibutsu", "feedback": "Not quite! Ushiku Daibutsu is a giant bronze Buddha statue in Japan.", "isCorrect": false}], "question": "Tallest statue in the world", "attemptsAllowed": 1}, {"id": "cmvj6audc000108jm2y9tihzw-2", "type": "image-select", "points": 1, "options": [{"id": "opt-1", "image": "img/1bd22ad935fb-statue-of-unity.webp", "label": "Statue of Unity", "feedback": "Not quite! The Statue of Unity is currently the tallest statue.", "isCorrect": false}, {"id": "opt-2", "image": "img/cf8561f9c513-spring-temple-buddha.webp", "label": "Spring Temple Buddha", "feedback": "Correct! The Spring Temple Buddha held the tallest-statue record before 2018.", "isCorrect": true}, {"id": "opt-3", "image": "img/1e83cf08d575-laykyun-sekkya.webp", "label": "Laykyun Sekkya", "feedback": "Not quite! Laykyun Sekkya is another monumental Buddha statue.", "isCorrect": false}, {"id": "opt-4", "image": "img/9852baea9657-ushiku-daibutsu.webp", "label": "Ushiku Daibutsu", "feedback": "Not quite! Ushiku Daibutsu is famous for its enormous bronze construction.", "isCorrect": false}], "question": "Second-tallest statue in the world", "attemptsAllowed": 1}, {"id": "cmvj6audc000108jm2y9tihzw-3", "type": "image-select", "points": 1, "options": [{"id": "opt-1", "image": "img/50972c229f9e-grand-buddha-of-lingshan.webp", "label": "Grand Buddha of Lingshan", "feedback": "Not quite! The Grand Buddha of Lingshan is a famous bronze Buddha.", "isCorrect": false}, {"id": "opt-2", "image": "img/775e4e3f87db-guishan-guanyin.webp", "label": "Guishan Guanyin", "feedback": "Not quite! Guishan Guanyin is a towering gilded bronze statue.", "isCorrect": false}, {"id": "opt-3", "image": "img/cf8561f9c513-spring-temple-buddha.webp", "label": "Spring Temple Buddha", "feedback": "Not quite! This enormous statue is not the answer given for this record in the source.", "isCorrect": false}, {"id": "opt-4", "image": "img/9852baea9657-ushiku-daibutsu.webp", "label": "Ushiku Daibutsu", "feedback": "Correct! Ushiku Daibutsu was recognized by Guinness in 1995 as the world''s tallest bronze statue.", "isCorrect": true}], "question": "Tallest bronze statue in the world (Guinness, 1995)", "attemptsAllowed": 1}, {"id": "cmvj6audc000108jm2y9tihzw-4", "type": "image-select", "points": 1, "options": [{"id": "opt-1", "image": "img/9852baea9657-ushiku-daibutsu.webp", "label": "Ushiku Daibutsu", "feedback": "Not quite! Ushiku Daibutsu is a bronze statue, but it is not gilded.", "isCorrect": false}, {"id": "opt-2", "image": "img/775e4e3f87db-guishan-guanyin.webp", "label": "Guishan Guanyin", "feedback": "Correct! Guishan Guanyin is identified in the source as the tallest gilded bronze statue.", "isCorrect": true}, {"id": "opt-3", "image": "img/d8739c0c42f5-tiantanbuddha.webp", "label": "Tian Tan Buddha", "feedback": "Not quite! Tian Tan Buddha is a famous outdoor bronze Buddha.", "isCorrect": false}, {"id": "opt-4", "image": "img/50972c229f9e-grand-buddha-of-lingshan.webp", "label": "Grand Buddha of Lingshan", "feedback": "Not quite! This statue is bronze but is not identified as the tallest gilded bronze statue.", "isCorrect": false}], "question": "Tallest gilded bronze statue", "attemptsAllowed": 1}, {"id": "cmvj6audc000108jm2y9tihzw-5", "type": "image-select", "points": 1, "options": [{"id": "opt-1", "image": "img/a533727787fd-monument-of-the-holy-mother-of-god.webp", "label": "Monument of the Holy Mother of God", "feedback": "Not quite! This monument represents Mary with the Infant Jesus, a more specific category.", "isCorrect": false}, {"id": "opt-2", "image": "img/8c98d23f5b3d-virgen-de-la-paz.webp", "label": "Virgen de la Paz", "feedback": "Not quite! Virgen de la Paz is another monumental Marian statue.", "isCorrect": false}, {"id": "opt-3", "image": "img/aa469d1d403b-our-lady-of-f-tima.webp", "label": "Our Lady of Fátima", "feedback": "Not quite! This is a Marian statue in Brazil, but it is not the answer listed in the source.", "isCorrect": false}, {"id": "opt-4", "image": "img/9476708ee9a5-mother-of-all-asia-tower-of-peace.webp", "label": "Mother of All Asia – Tower of Peace", "feedback": "Correct! The source identifies the Mother of All Asia as the world''s tallest statue of the Virgin Mary.", "isCorrect": true}], "question": "Tallest statue of the Virgin Mary in the world", "attemptsAllowed": 1}, {"id": "cmvj6audc000108jm2y9tihzw-6", "type": "image-select", "points": 1, "options": [{"id": "opt-1", "image": "img/01b3187f1591-statue-of-belief-shiva.webp", "label": "Statue of Belief (Shiva)", "feedback": "Not quite! Some sources classify this statue as a contender, depending on how the record is defined.", "isCorrect": false}, {"id": "opt-2", "image": "img/da692e39fe8e-garuda-wisnu-kencana.webp", "label": "Garuda Wisnu Kencana", "feedback": "Correct! Garuda Wisnu Kencana depicts Lord Vishnu riding Garuda.", "isCorrect": true}, {"id": "opt-3", "image": "img/f8fe14620664-statue-of-equality-ramanuja.webp", "label": "Statue of Equality (Ramanuja)", "feedback": "Not quite! The Statue of Equality is approximately 65.8 metres tall.", "isCorrect": false}, {"id": "opt-4", "image": "img/57da8b92b986-kailashnath-mahadev.webp", "label": "Kailashnath Mahadev", "feedback": "Not quite! This statue depicts Lord Shiva and is located in Nepal.", "isCorrect": false}], "question": "Tallest statue of a Hindu deity", "attemptsAllowed": 1}], "mapSubtitle": "Can you identify the statue?"}], "order": 0, "theme": "ThemeKEY", "title": "Statue", "author": "Bhumi", "category": "category", "weekLabel": "Thursday, October 22", "description": "Do you know the statues of the world?", "publishedAt": "2026-10-22", "estimatedTime": "10"}', '2026-10-22 07:00:12.673', '2026-10-22 07:01:10.256');
