INSERT INTO public.edition (id, title, description, theme, category, author, "coverImage", "estimatedTime", status, date, snapshot, "createdAt", "updatedAt") VALUES ('cmvm37ecc000208l595ic6qcj', 'Famous Paintings', 'Get to know the iconic paintings of all time!', 'Default', 'Art', 'Bhumi', NULL, '10', 'SCHEDULED', '2026-10-24', '{"id": "cmvm37ecc000208l595ic6qcj", "nodes": [{"id": "cmvm31nzd000108l510zrpz6h", "type": "image-text-answer", "mapTitle": "Paintings", "isPremium": false, "subStages": [{"id": "cmvm31nzd000108l510zrpz6h-1", "hint": "The artist behind this work was a Norwegian painter whose art often explored anxiety, loneliness, love, and death.", "type": "image-text-answer", "image": "img/b3e486020680-scream-by-edvard-munch.webp", "answer": "The Scream", "points": 10, "feedback": {"correct": "Correct! The Scream is a painting by Edvard Munch.", "incorrect": "Not quite. The painting is The Scream by Edvard Munch."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"id": "cmvm31nzd000108l510zrpz6h-2", "hint": "The title of this painting refers to the young women who served at the Spanish royal court. Look at the little girl in the centre—she is Infanta Margarita, the daughter of King Philip IV, surrounded by her ladies-in-waiting.", "type": "image-text-answer", "image": "img/64243f4ab0cf-las-meninas-by-diego-velazquez.webp", "answer": "Las Meninas", "points": 10, "feedback": {"correct": "Correct! Las Meninas by Diego Velázquez.", "incorrect": "Not quite. The painting is Las Meninas by Diego Velázquez."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"id": "cmvm31nzd000108l510zrpz6h-3", "hint": "The painting was originally commissioned as a romantic scene involving a young woman, her lover, and her husband.", "type": "image-text-answer", "image": "img/e7d4b773936d-the-swing-by-jean-honore-fragonard.webp", "answer": "The Swing", "points": 10, "feedback": {"correct": "Correct! The Swing by Jean-Honoré Fragonard.", "incorrect": "Not quite. The painting is The Swing by Jean-Honoré Fragonard."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"id": "cmvm31nzd000108l510zrpz6h-4", "hint": "Look closely at the figures. They are dressed in elaborate, almost theatrical clothing, and several are holding or playing musical instruments.", "type": "image-text-answer", "image": "img/b0a61bc450d7-musicians-by-caravaggio.webp", "answer": "The Musicians", "points": 10, "feedback": {"correct": "Correct! It''s The Musicians by Caravaggio.", "incorrect": "Not quite. It''s The Musicians by Caravaggio."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"id": "cmvm31nzd000108l510zrpz6h-5", "hint": "The central figure is Venus, the Roman goddess of love, surrounded by other mythological characters.", "type": "image-text-answer", "image": "img/df90461ad061-primavera-by-sandro-botticelli.webp", "answer": "Primavera", "points": 10, "feedback": {"correct": "Correct! The painting is Primavera by Sandro Botticelli.", "incorrect": "Not quite. The painting is Primavera by Sandro Botticelli."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"id": "cmvm31nzd000108l510zrpz6h-6", "hint": "The title comes from the act of collecting the small amounts of grain left behind after harvesting.", "type": "image-text-answer", "image": "img/7882867e6081-the-gleaners-by-jean-francois-millet.webp", "answer": "The Gleaners", "points": 10, "feedback": {"correct": "Correct! It is The Gleaners by Jean-François Millet.", "incorrect": "Not quite. It is The Gleaners by Jean-François Millet."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"id": "cmvm31nzd000108l510zrpz6h-7", "hint": "The title is a woman''s name that was often associated with courtesans in 19th-century Paris.", "type": "image-text-answer", "image": "img/7e0193b26cc9-olympia-by-edouard-manet.webp", "answer": "Olympia", "points": 10, "feedback": {"correct": "Correct! The painting is Olympia by Édouard Manet.", "incorrect": "Not quite. The painting is Olympia by Édouard Manet."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"id": "cmvm31nzd000108l510zrpz6h-8", "hint": "The person in the painting is studying the stars and planets rather than the Earth; his profession gives the painting its title.", "type": "image-text-answer", "image": "img/49632a183050-the-astronomer-by-johannes-vermeer.webp", "answer": "The Astronomer", "points": 10, "feedback": {"correct": "Correct! It is The Astronomer by Johannes Vermeer.", "incorrect": "Not quite. It is The Astronomer by Johannes Vermeer."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"id": "cmvm31nzd000108l510zrpz6h-9", "hint": "The title tells you both when the scene takes place and the kind of place we are looking at.", "type": "image-text-answer", "image": "img/2e9d77e07179-the-night-cafe-by-vincent-van-gogh.webp", "answer": "The Night Cafe", "points": 10, "feedback": {"correct": "Correct! The painting is The Night Cafe by Vincent van Gogh.", "incorrect": "Not quite. The painting is The Night Cafe by Vincent van Gogh."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"id": "cmvm31nzd000108l510zrpz6h-10", "hint": "The French artist painted this subject again and again, inspired by the water garden at his home in Giverny.", "type": "image-text-answer", "image": "img/480e863f485e-water-lilies-by-claude-monet.webp", "answer": "Water Lilies", "points": 10, "feedback": {"correct": "Correct! It is Water Lilies by Claude Monet.", "incorrect": "Not quite. It is Water Lilies by Claude Monet."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}], "mapSubtitle": "Guess what you see"}], "order": 0, "theme": "Default", "title": "Famous Paintings", "author": "Bhumi", "category": "Art", "weekLabel": "Saturday, October 24", "description": "Get to know the iconic paintings of all time!", "publishedAt": "2026-10-24", "estimatedTime": "10"}', '2026-10-24 07:38:22.428', '2026-10-24 07:38:41.16');
INSERT INTO public.edition (id, title, description, theme, category, author, "coverImage", "estimatedTime", status, date, snapshot, "createdAt", "updatedAt") VALUES ('cmvnrwg7z000207l8f8d4sb0q', 'History of Colours', 'Get to know the history of colours, how some colours just came into human civilization.', 'colours', 'History', 'Bh', NULL, '10', 'SCHEDULED', '2026-10-25', '{"id": "cmvnrwg7z000207l8f8d4sb0q", "nodes": [{"id": "cmvnruf4k000107l8k78z2osw", "type": "color-match", "mapTitle": "Color", "isPremium": false, "subStages": [{"id": "cmvnruf4k000107l8k78z2osw-1", "type": "color-match", "clues": [{"id": "Saffron", "hex": "#F4C430", "hint": "For most of history this dye traded at nearly the same value as gold and silver by weight. Only three stigmas can be hand-plucked per flower, which is why the price has never really dropped.", "name": "Saffron", "clue1": "It takes about 150,000 hand-picked, dried crocus flowers to produce just 1 kilogram of this dye."}, {"id": "Prussian Blue", "hex": "#003153", "hint": "The compound became an FDA-approved antidote for radioactive cesium and thallium poisoning, is stocked in nuclear emergency kits worldwide, enabled cyanotype blueprints, and was quickly adopted for Prussian army uniforms.", "name": "Prussian Blue", "clue1": "A dye-maker in 1704 was trying to invent a red pigment from crushed cochineal insects but accidentally created this instead."}, {"id": "Tyrian Purple", "hex": "#66023C", "hint": "In 2024, Paris Olympics organizers chose this exact hue for the running track at the Stade de France, the first time in Olympic history the surface was not red or blue.", "name": "Tyrian Purple", "clue1": "Dye-makers had to crack open roughly 12,000 sea snails to extract enough gland fluid to color a single garment hem."}, {"id": "Pompeian Red", "hex": "#A4292E", "hint": "Lab analysis found the original pigment was yellow ochre, transformed within moments by superheated volcanic gas during the 79 CE eruption, inspiring the same colour on government buildings across many Indian cities.", "name": "Pompeian Red", "clue1": "In 2023, scientists found that many walls at this ancient Roman site were never actually painted this color—it appeared by accident."}, {"id": "Indigo", "hex": "#4B0082", "hint": "Colonial planters coercively forced Bengali and Bihari farmers to grow this crop for the European dye trade, sparking the 1859 revolt and later leading Gandhi to Champaran in 1917 for his first satyagraha.", "name": "Indigo", "clue1": "A dye helped start a movement against the British Raj in Colonial India."}, {"id": "Mummy Brown", "hex": "#824B27", "hint": "Art suppliers sourced Egyptian mummies specifically to grind their wrappings, resin, and tissue into pigment for oil painting.", "name": "Mummy Brown", "clue1": "From the 1500s to the early 1900s, this paint was made by grinding up actual embalmed human remains."}], "points": 100, "prompt": "This is a prompt", "feedback": {"correct": "Great Eye!", "incorrect": "Not quite — try again and watch for the small details."}, "question": "Colors and their Stories", "attemptsAllowed": 3}], "mapSubtitle": "Drag each color to its story."}], "order": 0, "theme": "colours", "title": "History of Colours", "author": "Bh", "category": "History", "weekLabel": "Sunday, October 25", "description": "Get to know the history of colours, how some colours just came into human civilization.", "publishedAt": "2026-10-25", "estimatedTime": "10"}', '2026-10-25 11:57:28.223', '2026-10-25 11:57:36.815');
INSERT INTO public.edition (id, title, description, theme, category, author, "coverImage", "estimatedTime", status, date, snapshot, "createdAt", "updatedAt") VALUES ('cmvqdexes000008l8o1kja56c', 'Colors', 'Arrange the events in chronological order.', 'Colors', 'History', 'Bhumika', NULL, '5 mins', 'SCHEDULED', '2026-10-27', '{"id": "cmvqdexes000008l8o1kja56c", "nodes": [{"id": "cmvp4zdjk000107lhkz46zreb", "type": "timeline-builder", "mapTitle": "Colours", "isPremium": false, "subStages": [{"id": "cmvp4zdjk000107lhkz46zreb-1", "type": "timeline-builder", "events": [{"id": "timeline-event-001", "year": "2500 BCE", "image": "img/f6fcc32da2e0-egyptian-blue.webp", "order": 1, "title": "Ancient Egypt''s Invention of Blue", "description": "Egyptian artisans heated sand, copper, and limestone together to create Egyptian Blue, considered the oldest known synthetic pigment in history. It was used for coloring the skin of gods and the beards of pharaohs'' statues to represent the heavens, the Nile, and rebirth."}, {"id": "timeline-event-002", "year": "1666", "image": "img/743d7ca2d6df-newton-prism.webp", "order": 2, "title": "Isaac Newton Discovers the Colours in White Light", "description": "Isaac Newton, working alone at Woolsthorpe Manor after Cambridge University closed due to plague, darkened his room, drilled a small hole in the shutter, and passed a beam of sunlight through a glass prism. He proved that white light is made of red, orange, yellow, green, blue, indigo, and violet combined."}, {"id": "timeline-event-003", "year": "1840", "image": "img/961f534c4899-queen-victoria-wedding.webp", "order": 3, "title": "The White Wedding Gown Tradition", "description": "Queen Victoria wore a plain white gown for her wedding to Prince Albert, instead of the elaborate, richly coloured robes expected of royalty. Newspapers described the white dress in detail, and brides across Britain began copying her choice, helping popularize the white wedding dress tradition."}, {"id": "timeline-event-004", "year": "1901–1904", "image": "img/9b2a6d2ba089-picasso-blue-period.webp", "order": 4, "title": "The Blue Period in Art", "description": "After the suicide of his close friend Carlos Casagemas, Pablo Picasso painted almost exclusively in shades of blue and blue-green for several years. Art historians now call this his Blue Period."}, {"id": "timeline-event-005", "year": "1978", "image": "img/54a16cb89f1d-gilbert-baker-rainbow-flag.webp", "order": 5, "title": "The Eight-Striped Rainbow Flag", "description": "Gilbert Baker, an artist and U.S. Army veteran living in San Francisco, hand-dyed and hand-sewed an eight-striped flag featuring hot pink, red, orange, yellow, green, turquoise, indigo, and violet, to fly at the San Francisco Gay Freedom Day Parade. Within about a year, the hot pink and turquoise stripes were dropped because the dyed fabric was too hard to source in bulk, leaving the six-colour rainbow flag recognised today."}, {"id": "timeline-event-006", "year": "2012", "image": "img/5c9177531b06-pink-blue-gender-colors.webp", "order": 6, "title": "Pink for Girls, Blue for Boys?", "description": "Psychologist Marco Del Giudice used Google''s book-scanning database to search millions of printed books for the phrases ''blue for boys'' and ''pink for girls.'' He found the pink-for-girls, blue-for-boys pairing had actually been consistent since the late 1800s, contradicting the popular claim that the colours were once reversed."}, {"id": "timeline-event-007", "year": "2015", "image": "img/62084f51a730-pink-cricket-ball.webp", "order": 7, "title": "Cricket''s First Day-Night Test with a Pink Ball", "description": "Australia and New Zealand played the first day-night Test match in cricket''s 138-year history, at Adelaide Oval. Since a traditional red ball is nearly invisible under floodlights, organisers used a specially coated pink ball instead, chosen after years of trials for staying visible against both grass and a darkening sky."}, {"id": "timeline-event-008", "year": "2016", "image": "img/eafa7ef10df1-unicorn-frappuccino.webp", "order": 8, "title": "The Millennial Pink Trend", "description": "Starbucks released the limited-edition Unicorn Frappuccino, a pink-and-blue layered drink, for a single weekend. It sold out at locations worldwide within hours and became one of the defining products of the ''millennial pink'' wave that had already been building across fashion, design, and Instagram since the term was first coined by New York Magazine."}], "points": 10, "question": "Arrange the events in chronological order.", "instructions": "Drag each historical event to its correct place on the timeline.", "estimatedTime": "5 mins", "attemptsAllowed": 1}], "mapSubtitle": "Arrange the events in chronological order."}], "order": 0, "theme": "Colors", "title": "Colors", "author": "Bhumika", "category": "History", "weekLabel": "Tuesday, October 27", "description": "Arrange the events in chronological order.", "publishedAt": "2026-10-27", "estimatedTime": "5 mins"}', '2026-10-27 07:35:14.596', '2026-10-27 07:37:23.351');
INSERT INTO public.edition (id, title, description, theme, category, author, "coverImage", "estimatedTime", status, date, snapshot, "createdAt", "updatedAt") VALUES ('cmvrsrsa9000007jph9kynl4q', 'Sufism', 'Discover Sufism through the poetry of games.', 'sufi-mysticism', 'Culture', 'Bhumika', NULL, '5 mins', 'SCHEDULED', '2026-10-28', '{"id": "cmvrsrsa9000007jph9kynl4q", "nodes": [{"id": "cmvnt1agq000107l880r4tfo3", "type": "fill-blank-text", "mapTitle": "Sufism", "isPremium": false, "subStages": [{"id": "cmvnt1agq000107l880r4tfo3-1", "type": "fill-blank-text", "blanks": [{"id": "b1", "answer": "Prithviraj Chauhan"}], "points": 10, "prompt": "In 1192, {{b1}}, the legendary Rajput warrior, was defeated by Muizuddin Muhammad bin Sam at the Second Battle of Tarain, opening India to Islamic mysticism. Four years later, Khwaja Moinuddin Chishti arrived from Afghanistan and established the Chishti Order, a spiritual movement that would transform Indian spirituality for the next 800 years.", "feedback": {"correct": "Yay! You know this topic very well.", "incorrect": "No worries!! You can learn more about this at the end of this session."}, "question": "Fill in the missing words", "attemptsAllowed": 1}, {"id": "cmvnt1agq000107l880r4tfo3-2", "type": "fill-blank-text", "blanks": [{"id": "b1", "answer": "Ajmer"}], "points": 10, "prompt": "{{b1}}, Rajasthan, became the heart of Indian Sufism after Khwaja Moinuddin Chishti settled there in 1196, establishing Islam’s most visited shrine, which attracts 20,000+ pilgrims daily and 400,000+ during the annual Urs in Rajab, the 7th Islamic month. Its most sacred ceremony, Chhati Sharif, held on the 6th day, the recitation of the Chishti Order’s genealogical tree and concludes with a 21 gun salute.", "feedback": {"correct": "Yay! You know this topic very well.", "incorrect": "No worries!! You can learn more about this at the end of this session."}, "question": "Fill in the missing words", "attemptsAllowed": 1}, {"id": "cmvnt1agq000107l880r4tfo3-3", "type": "fill-blank-text", "blanks": [{"id": "b1", "answer": "Basant Panchami"}], "points": 10, "prompt": "Delhi''s Nizamuddin Dargah celebrates {{b1}}, the 5th day of the Hindu lunar month Phalgun, marking spring''s arrival. Devotees drape the dargah in yellow flowers, symbolizing renewal and the Sufi concept of \"noor\" (divine light). This Hindu-Islamic fusion, 700+ years old, shows how Sufism wove spirituality across religious boundaries.", "feedback": {"correct": "Yay! You know this topic very well.", "incorrect": "No worries!! You can learn more about this at the end of this session."}, "question": "Fill in the missing words", "attemptsAllowed": 1}, {"id": "cmvnt1agq000107l880r4tfo3-4", "type": "fill-blank-text", "blanks": [{"id": "b1", "answer": "Amir Khusrow"}], "points": 10, "prompt": "In 1244–1325, {{b1}} became one of Sufism’s greatest voices, was known as the “Nightingale of India.\" Though his master Hazrat Nizamuddin Auliya had 600+ khalifas (authorized disciples), he alone was declared his most beloved. The irony was profound: despite Nizamuddin’s view that musical instruments were haram (forbidden), his beloved disciple is credited with inventing the musical instrument and creating Qawwali, the musical form that made Sufism globally famous.", "feedback": {"correct": "Yay! You know this topic very well.", "incorrect": "No worries!! You can learn more about this at the end of this session."}, "question": "Fill in the missing words", "attemptsAllowed": 1}, {"id": "cmvnt1agq000107l880r4tfo3-5", "type": "fill-blank-text", "blanks": [{"id": "b1", "answer": "Tabla"}], "points": 10, "prompt": "According to legend, he split the traditional pakhawaj (barrel drum) into two drums for Sufi music one the high-pitched dayan and deep bass bayan, creating the {{b1}}. Another tale claims Mughal musician Tansen''s accompanist''s pakhawaj cracked during performance, and Tansen exclaimed \"Tab bhi bola!\" (It still sounds!) supposedly naming the instrument from that moment.", "feedback": {"correct": "Yay! You know this topic very well.", "incorrect": "No worries!! You can learn more about this at the end of this session."}, "question": "Fill in the missing words", "attemptsAllowed": 1}, {"id": "cmvnt1agq000107l880r4tfo3-6", "type": "fill-blank-text", "blanks": [{"id": "b1", "answer": "Whirling"}], "points": 10, "prompt": "The Turkish Mevlevi Order expressed spiritual devotion through {{b1}}, a ritual association with Rumi that was proclaimed a UNESCO Masterpiece of Oral and Intangible Heritage in 2005. The Arabic word samāʿ means \"listening\" or \"hearing\", making this movement a physical expression of spiritual listening through music, poetry, and prayer.", "feedback": {"correct": "Yay! You know this topic very well.", "incorrect": "No worries!! You can learn more about this at the end of this session."}, "question": "Fill in the missing words", "attemptsAllowed": 1}, {"id": "cmvnt1agq000107l880r4tfo3-7", "type": "fill-blank-text", "blanks": [{"id": "b1", "answer": "Rabia"}], "points": 10, "prompt": "{{b1}} (the First Woman Sufi Saint), born into 8th-century Basra poverty, her name meaning ''fourth daughter'' became history''s first feminist mystic. Orphaned and enslaved, she prayed all night until her master witnessed divine light surrounding her. She rejected all marriage proposals, declaring marriage would distract her from God, act of radical autonomy in 8th-century Arabia.", "feedback": {"correct": "Yay! You know this topic very well.", "incorrect": "No worries!! You can learn more about this at the end of this session."}, "question": "Fill in the missing words", "attemptsAllowed": 1}, {"id": "cmvnt1agq000107l880r4tfo3-8", "type": "fill-blank-text", "blanks": [{"id": "b1", "answer": "Langar"}], "points": 10, "prompt": "{{b1}}, a Persian institution within the Chishti Order, gives food and drink to the needy regardless of background. Sugar represents piety''s sweetness; salt symbolizes purity; bread''s transformation mirrors Sufi spiritual development and nafs (ego) purification.", "feedback": {"correct": "Yay! You know this topic very well.", "incorrect": "No worries!! You can learn more about this at the end of this session."}, "question": "Fill in the missing words", "attemptsAllowed": 1}, {"id": "cmvnt1agq000107l880r4tfo3-9", "type": "fill-blank-text", "blanks": [{"id": "b1", "answer": "Calligraphy"}], "points": 10, "prompt": "Sufi {{b1}} was an act of worship, not decoration. Each letter of Allah''s name was traced with spiritual intention, making the scribe a mystic. \"Tezhip\" (gilding) the golden illuminations in Qur''an manuscripts—served as spiritual technology to lift consciousness toward Paradise. Ink, paper, and brush became meditation tools as powerful as prayer. \nThrough saints and musicians, food and flowers, ink and rhythm, Sufism transformed from a response to political upheaval into a comprehensive spiritual path. The divine is reached through listening, service, love, and surrender of the self—the greatest transformation of all.", "feedback": {"correct": "Yay! You know this topic very well.", "incorrect": "No worries!! You can learn more about this at the end of this session."}, "question": "Fill in the missing words", "attemptsAllowed": 1}], "mapSubtitle": ""}], "order": 0, "theme": "sufi-mysticism", "title": "Sufism", "author": "Bhumika", "category": "Culture", "weekLabel": "Wednesday, October 28", "description": "Discover Sufism through the poetry of games.", "publishedAt": "2026-10-28", "estimatedTime": "5 mins"}', '2026-10-28 07:32:54.897', '2026-10-28 07:34:33.355');


