INSERT INTO public.game (id, type, title, subtitle, "isPremium", "subStages", "schemaVersion", "importBatchId", "editionId", "position", "createdAt", "updatedAt") VALUES ('cmvnt1rlk000907l8loxqdgpe', 'drag-drop', 'Space Links', NULL, false, '[{"map": {"slots": [{"id": "slot-salt", "label": "Latin word for salt", "anchor": "r2c2", "answerCardId": "salt"}], "title": "Step 1", "pattern": "lattice-3x4", "pathStyle": "orthogonal", "relations": [{"id": "latin-sal", "color": "#c7a0ff", "label": "Means salt in Latin", "anchor": "r1c2", "slotIds": ["slot-salt"]}]}, "cards": [{"id": "salt", "color": "#c7a0ff", "image": "/images/placeholders/salt.png", "title": "Salt"}], "points": 50, "prompt": "Find the word connected to the Latin root.", "feedback": {"correct": "Exactly. ''Sal'' is the Latin word for salt.", "incorrect": "Think about the Latin root ''sal''. What does it mean?"}, "learning": {"title": "Start with the root", "message": "The Latin word ''sal'' means salt. Remember this connection because it will help you discover other words.", "takeaway": "SAL = LATIN FOR SALT"}, "question": "Discover the root behind these words", "introLabel": "Discover 1", "attemptsAllowed": 3}, {"map": {"slots": [{"id": "slot-salt", "label": "Latin word for salt", "anchor": "r1c1", "answerCardId": "salt"}, {"id": "slot-salad", "label": "Named for salted vegetables and herbs", "anchor": "r3c1", "answerCardId": "salad"}], "title": "Step 2", "pattern": "lattice-3x4", "pathStyle": "orthogonal", "relations": [{"id": "latin-root", "color": "#c7a0ff", "label": "Latin root meaning salt", "anchor": "r1c2", "slotIds": ["slot-salt", "slot-salad"]}, {"id": "salted-vegetables", "color": "#66cfd3", "label": "Romans ate vegetables and herbs prepared with salt", "anchor": "r2c2", "slotIds": ["slot-salad"]}]}, "cards": [{"id": "salt", "color": "#c7a0ff", "image": "/images/placeholders/salt.png", "title": "Sal"}, {"id": "salad", "color": "#66cfd3", "image": "/images/placeholders/salad.png", "title": "Salad"}], "points": 60, "prompt": "Use what you just learned to find the next connection.", "feedback": {"correct": "Nice. You discovered the connection between sal and salad.", "incorrect": "Remember: sal means salt, and salad is connected to salted vegetables."}, "learning": {"title": "Follow SAL", "message": "Romans ate vegetables and herbs that were salted. This helped give rise to the word ''salad''.", "takeaway": "SAL → SALTED VEGETABLES → SALAD"}, "question": "Discover how SAL became part of another everyday word", "introLabel": "Discover 2", "attemptsAllowed": 3}, {"map": {"slots": [{"id": "slot-salt", "label": "Latin word for salt", "anchor": "r1c1", "answerCardId": "salt"}, {"id": "slot-salary", "label": "Modern word connected to a Roman allowance", "anchor": "r3c1", "answerCardId": "salary"}], "title": "Step 3", "pattern": "lattice-3x4", "pathStyle": "orthogonal", "relations": [{"id": "root-sal", "color": "#c7a0ff", "label": "Comes from the Latin word for salt", "anchor": "r2c1", "slotIds": ["slot-salt", "slot-salary"]}, {"id": "roman-allowance", "color": "#86ce5d", "label": "Given as a special Roman soldier''s allowance", "anchor": "r2c2", "slotIds": ["slot-salary"]}, {"id": "salarium", "color": "#ffb1bd", "label": "This allowance was called ''salarium''", "anchor": "r3c2", "slotIds": ["slot-salary"]}]}, "cards": [{"id": "salt", "color": "#c7a0ff", "image": "/images/placeholders/salt.png", "title": "Sal"}, {"id": "salary", "color": "#ffb1bd", "image": "/images/placeholders/salary.png", "title": "Salary"}], "points": 70, "prompt": "Follow the clues from salt to a modern word.", "feedback": {"correct": "You found the chain: sal → salarium → salary.", "incorrect": "Think about the Roman soldier''s special allowance. What was it called?"}, "learning": {"title": "Salt became an allowance", "message": "Roman soldiers received a special allowance associated with salt. This allowance was called ''salarium''. The modern word ''salary'' developed from this word.", "takeaway": "SAL → SALARIUM → SALARY"}, "question": "Discover the Roman connection", "introLabel": "Discover 3", "attemptsAllowed": 3}, {"map": {"slots": [{"id": "slot-salsa", "label": "Spanish word meaning ''salted''", "anchor": "r1c1", "answerCardId": "salsa"}, {"id": "slot-sauce", "label": "French word for a savory condiment", "anchor": "r3c1", "answerCardId": "sauce"}], "title": "Step 4", "pattern": "lattice-3x4", "pathStyle": "orthogonal", "relations": [{"id": "salsus-root", "color": "#c7a0ff", "label": "Ultimately comes from Latin ''salsus'' meaning salted", "anchor": "r1c2", "slotIds": ["slot-salsa", "slot-sauce"]}, {"id": "savory-flavoring", "color": "#ffb65c", "label": "Both are savory, salt-based flavorings", "anchor": "r2c2", "slotIds": ["slot-salsa", "slot-sauce"]}]}, "cards": [{"id": "salsa", "color": "#c7a0ff", "image": "/images/placeholders/salsa.png", "title": "Salsa"}, {"id": "sauce", "color": "#ffb65c", "image": "/images/placeholders/sauce.png", "title": "Sauce"}], "points": 80, "prompt": "Find the words connected to the Latin idea of ''salted''.", "feedback": {"correct": "Good. You discovered another branch of the salt-related word family.", "incorrect": "Look for the words connected to the Latin idea of ''salted''."}, "learning": {"title": "Meet SALSUS", "message": "The Latin word ''salsus'' meant salted. Several food-related words developed from this Latin root.", "takeaway": "SALSUS = SALTED"}, "question": "Discover words connected to the idea of ''salted''", "introLabel": "Discover 4", "attemptsAllowed": 3}, {"map": {"slots": [{"id": "slot-salami", "label": "Italian cured, salted meat", "anchor": "r2c1", "answerCardId": "salami"}, {"id": "slot-sausage", "label": "Food preserved by curing with salt", "anchor": "r3c3", "answerCardId": "sausage"}], "title": "Step 5", "pattern": "lattice-3x4", "pathStyle": "orthogonal", "relations": [{"id": "salt-preservative", "color": "#86ce5d", "label": "Made using salt as a preservative", "anchor": "r2c2", "slotIds": ["slot-salami", "slot-sausage"]}, {"id": "moisture", "color": "#fff27a", "label": "Salt draws out moisture to help preserve food", "anchor": "r3c2", "slotIds": ["slot-salami", "slot-sausage"]}]}, "cards": [{"id": "salami", "color": "#86ce5d", "image": "/images/placeholders/salami.png", "title": "Salami"}, {"id": "sausage", "color": "#fff27a", "image": "/images/placeholders/sausage.png", "title": "Sausage"}], "points": 90, "prompt": "Connect salt with the way it preserves food.", "feedback": {"correct": "Exactly. Salt can help preserve food by drawing out moisture.", "incorrect": "Think about what salt does to moisture in food."}, "learning": {"title": "Salt does more than add flavor", "message": "Salt draws moisture out of food. Reducing moisture helps preserve food, which is why salt has long been used when curing meat.", "takeaway": "SALT → DRAWS OUT MOISTURE → HELPS PRESERVE FOOD"}, "question": "Discover how salt helps preserve food", "introLabel": "Discover 5", "attemptsAllowed": 3}, {"map": {"slots": [{"id": "slot-sal", "label": "Latin word for salt", "anchor": "r1c1", "answerCardId": "sal"}, {"id": "slot-salsa", "label": "Spanish word meaning ''salted''", "anchor": "r1c3", "answerCardId": "salsa"}, {"id": "slot-salad", "label": "Named for salted vegetables", "anchor": "r2c2", "answerCardId": "salad"}, {"id": "slot-salary", "label": "Modern word connected to a Roman allowance", "anchor": "r3c1", "answerCardId": "salary"}, {"id": "slot-salami", "label": "Italian cured, salted meat", "anchor": "r3c3", "answerCardId": "salami"}, {"id": "slot-sausage", "label": "Food preserved by curing with salt", "anchor": "r4c2", "answerCardId": "sausage"}], "title": "Final Map", "pattern": "lattice-3x4", "pathStyle": "orthogonal", "relations": [{"id": "sal-root", "color": "#c7a0ff", "label": "Latin root connected to salt", "anchor": "r1c2", "slotIds": ["slot-sal", "slot-salad", "slot-salary"]}, {"id": "salsus-root", "color": "#66cfd3", "label": "Ultimately from Latin ''salsus'' meaning salted", "anchor": "r2c1", "slotIds": ["slot-salsa"]}, {"id": "salad-connection", "color": "#ffb65c", "label": "Salted vegetables and herbs", "anchor": "r2c3", "slotIds": ["slot-salad"]}, {"id": "salary-connection", "color": "#86ce5d", "label": "Roman soldiers received a special allowance", "anchor": "r3c2", "slotIds": ["slot-salary"]}, {"id": "preservation", "color": "#ffb1bd", "label": "Salt used as a preservative", "anchor": "r4c1", "slotIds": ["slot-salami", "slot-sausage"]}, {"id": "moisture", "color": "#fff27a", "label": "Salt draws out moisture to help preserve food", "anchor": "r4c3", "slotIds": ["slot-salami", "slot-sausage"]}]}, "cards": [{"id": "sal", "color": "#c7a0ff", "image": "/images/placeholders/salt.png", "title": "Sal"}, {"id": "salsa", "color": "#66cfd3", "image": "/images/placeholders/salsa.png", "title": "Salsa"}, {"id": "salad", "color": "#ffb65c", "image": "/images/placeholders/salad.png", "title": "Salad"}, {"id": "salary", "color": "#86ce5d", "image": "/images/placeholders/salary.png", "title": "Salary"}, {"id": "salami", "color": "#ffb1bd", "image": "/images/placeholders/salami.png", "title": "Salami"}, {"id": "sausage", "color": "#fff27a", "image": "/images/placeholders/sausage.png", "title": "Sausage"}], "points": 120, "prompt": "Use everything you have learned to complete the final map.", "feedback": {"correct": "Brilliant. You connected the complete salt network.", "incorrect": "You''ve learned the pieces. Now look for the relationships between salt, word origins, history, and preservation."}, "learning": {"title": "Put the whole story together", "message": "You''ve discovered how salt connects language, history, food, and preservation. Now connect the ideas yourself.", "takeaway": "SAL → SALAD and SALARIUM → SALARY. SALSUS → SALSA and SAUCE. Salt also helps preserve food by drawing out moisture."}, "question": "Connect everything you''ve discovered", "introLabel": "Final Challenge", "attemptsAllowed": 3}]', 1, 'cmvnt1rl4000807l85qyl598x', NULL, NULL, '2026-10-25 12:29:35.848', '2026-10-25 12:29:35.848');
INSERT INTO public.game (id, type, title, subtitle, "isPremium", "subStages", "schemaVersion", "importBatchId", "editionId", "position", "createdAt", "updatedAt") VALUES ('cmvm31nzd000108l510zrpz6h', 'image-text-answer', 'Paintings', 'Guess what you see', false, '[{"hint": "The artist behind this work was a Norwegian painter whose art often explored anxiety, loneliness, love, and death.", "image": "img/b3e486020680-scream-by-edvard-munch.webp", "answer": "The Scream", "points": 10, "feedback": {"correct": "Correct! The Scream is a painting by Edvard Munch.", "incorrect": "Not quite. The painting is The Scream by Edvard Munch."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"hint": "The title of this painting refers to the young women who served at the Spanish royal court. Look at the little girl in the centre—she is Infanta Margarita, the daughter of King Philip IV, surrounded by her ladies-in-waiting.", "image": "img/64243f4ab0cf-las-meninas-by-diego-velazquez.webp", "answer": "Las Meninas", "points": 10, "feedback": {"correct": "Correct! Las Meninas by Diego Velázquez.", "incorrect": "Not quite. The painting is Las Meninas by Diego Velázquez."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"hint": "The painting was originally commissioned as a romantic scene involving a young woman, her lover, and her husband.", "image": "img/e7d4b773936d-the-swing-by-jean-honore-fragonard.webp", "answer": "The Swing", "points": 10, "feedback": {"correct": "Correct! The Swing by Jean-Honoré Fragonard.", "incorrect": "Not quite. The painting is The Swing by Jean-Honoré Fragonard."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"hint": "Look closely at the figures. They are dressed in elaborate, almost theatrical clothing, and several are holding or playing musical instruments.", "image": "img/b0a61bc450d7-musicians-by-caravaggio.webp", "answer": "The Musicians", "points": 10, "feedback": {"correct": "Correct! It''s The Musicians by Caravaggio.", "incorrect": "Not quite. It''s The Musicians by Caravaggio."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"hint": "The central figure is Venus, the Roman goddess of love, surrounded by other mythological characters.", "image": "img/df90461ad061-primavera-by-sandro-botticelli.webp", "answer": "Primavera", "points": 10, "feedback": {"correct": "Correct! The painting is Primavera by Sandro Botticelli.", "incorrect": "Not quite. The painting is Primavera by Sandro Botticelli."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"hint": "The title comes from the act of collecting the small amounts of grain left behind after harvesting.", "image": "img/7882867e6081-the-gleaners-by-jean-francois-millet.webp", "answer": "The Gleaners", "points": 10, "feedback": {"correct": "Correct! It is The Gleaners by Jean-François Millet.", "incorrect": "Not quite. It is The Gleaners by Jean-François Millet."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"hint": "The title is a woman''s name that was often associated with courtesans in 19th-century Paris.", "image": "img/7e0193b26cc9-olympia-by-edouard-manet.webp", "answer": "Olympia", "points": 10, "feedback": {"correct": "Correct! The painting is Olympia by Édouard Manet.", "incorrect": "Not quite. The painting is Olympia by Édouard Manet."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"hint": "The person in the painting is studying the stars and planets rather than the Earth; his profession gives the painting its title.", "image": "img/49632a183050-the-astronomer-by-johannes-vermeer.webp", "answer": "The Astronomer", "points": 10, "feedback": {"correct": "Correct! It is The Astronomer by Johannes Vermeer.", "incorrect": "Not quite. It is The Astronomer by Johannes Vermeer."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"hint": "The title tells you both when the scene takes place and the kind of place we are looking at.", "image": "img/2e9d77e07179-the-night-cafe-by-vincent-van-gogh.webp", "answer": "The Night Cafe", "points": 10, "feedback": {"correct": "Correct! The painting is The Night Cafe by Vincent van Gogh.", "incorrect": "Not quite. The painting is The Night Cafe by Vincent van Gogh."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}, {"hint": "The French artist painted this subject again and again, inspired by the water garden at his home in Giverny.", "image": "img/480e863f485e-water-lilies-by-claude-monet.webp", "answer": "Water Lilies", "points": 10, "feedback": {"correct": "Correct! It is Water Lilies by Claude Monet.", "incorrect": "Not quite. It is Water Lilies by Claude Monet."}, "question": "What''s the name of this famous painting?", "introLabel": "Visual Guess", "attemptsAllowed": 2}]', 1, 'cmvm31nyv000008l5311bvyh7', 'cmvm37ecc000208l595ic6qcj', 0, '2026-10-24 07:33:54.967', '2026-10-24 07:38:31.12');
INSERT INTO public.game (id, type, title, subtitle, "isPremium", "subStages", "schemaVersion", "importBatchId", "editionId", "position", "createdAt", "updatedAt") VALUES ('cmvnruf4k000107l8k78z2osw', 'color-match', 'Color', 'Drag each color to its story.', false, '[{"clues": [{"id": "Saffron", "hex": "#F4C430", "hint": "For most of history this dye traded at nearly the same value as gold and silver by weight. Only three stigmas can be hand-plucked per flower, which is why the price has never really dropped.", "name": "Saffron", "clue1": "It takes about 150,000 hand-picked, dried crocus flowers to produce just 1 kilogram of this dye."}, {"id": "Prussian Blue", "hex": "#003153", "hint": "The compound became an FDA-approved antidote for radioactive cesium and thallium poisoning, is stocked in nuclear emergency kits worldwide, enabled cyanotype blueprints, and was quickly adopted for Prussian army uniforms.", "name": "Prussian Blue", "clue1": "A dye-maker in 1704 was trying to invent a red pigment from crushed cochineal insects but accidentally created this instead."}, {"id": "Tyrian Purple", "hex": "#66023C", "hint": "In 2024, Paris Olympics organizers chose this exact hue for the running track at the Stade de France, the first time in Olympic history the surface was not red or blue.", "name": "Tyrian Purple", "clue1": "Dye-makers had to crack open roughly 12,000 sea snails to extract enough gland fluid to color a single garment hem."}, {"id": "Pompeian Red", "hex": "#A4292E", "hint": "Lab analysis found the original pigment was yellow ochre, transformed within moments by superheated volcanic gas during the 79 CE eruption, inspiring the same colour on government buildings across many Indian cities.", "name": "Pompeian Red", "clue1": "In 2023, scientists found that many walls at this ancient Roman site were never actually painted this color—it appeared by accident."}, {"id": "Indigo", "hex": "#4B0082", "hint": "Colonial planters coercively forced Bengali and Bihari farmers to grow this crop for the European dye trade, sparking the 1859 revolt and later leading Gandhi to Champaran in 1917 for his first satyagraha.", "name": "Indigo", "clue1": "A dye helped start a movement against the British Raj in Colonial India."}, {"id": "Mummy Brown", "hex": "#824B27", "hint": "Art suppliers sourced Egyptian mummies specifically to grind their wrappings, resin, and tissue into pigment for oil painting.", "name": "Mummy Brown", "clue1": "From the 1500s to the early 1900s, this paint was made by grinding up actual embalmed human remains."}], "points": 100, "prompt": "This is a prompt", "feedback": {"correct": "Great Eye!", "incorrect": "Not quite — try again and watch for the small details."}, "question": "Colors and their Stories", "attemptsAllowed": 3}]', 1, 'cmvnruf40000007l86uj04mag', 'cmvnrwg7z000207l8f8d4sb0q', 0, '2026-10-25 11:55:53.472', '2026-10-25 11:57:31.036');
INSERT INTO public.game (id, type, title, subtitle, "isPremium", "subStages", "schemaVersion", "importBatchId", "editionId", "position", "createdAt", "updatedAt") VALUES ('cmvnt1e0f000307l8z2t1h274', 'fill-blank-text', 'Prison', 'Identify X', false, '[{"blanks": [{"id": "b1", "hint": "It is used to clean your teeth.", "answer": "Toothbrush"}], "points": 10, "prompt": "While serving time in a late-18th-century English prison for inciting a riot, William Addis fashioned the first mass-producible version of {{b1}} from a carved bone handle and boar bristles held in place by wire. He went on to die a wealthy man. In 1938, DuPont reworked it with nylon fibers, which proved sturdier and more efficient than animal hair. In the United States, daily use became widespread only after World War II veterans returned home with military hygiene habits. Identify X.", "feedback": {"correct": "Correct!", "incorrect": "Not quite. Think of the everyday hygiene tool William Addis helped popularize."}, "question": "Identify X", "introLabel": "Text Blank", "attemptsAllowed": 2}, {"blanks": [{"id": "b1", "hint": "It is the historic prison in the Andaman Islands, also associated with the term Kala Pani.", "answer": "Cellular Jail"}], "points": 10, "prompt": "Built between 1896 and 1906 with bricks from Burma, {{b1}} followed Jeremy Bentham''s panopticon: seven wings radiated from a central watchtower, with cells positioned so each faced the back of another wing, preventing communication. In 1872, Viceroy Lord Mayo was assassinated by Sher Ali Afridi, a convict in the earlier penal settlement here. In 1942, Subhas Chandra Bose''s Azad Hind government took notional control of the islands and hoisted the Indian National Flag. Only the watchtower and three wings survive today, and it became a national memorial in 1979. Its popular name evokes the sea crossing that threatened convicts with loss of caste. Identify X.", "feedback": {"correct": "Correct! The answer is Cellular Jail, also known as Kala Pani.", "incorrect": "Not quite. Think of the historic prison in the Andaman Islands."}, "question": "Identify X", "introLabel": "Text Blank", "attemptsAllowed": 2}, {"blanks": [{"id": "b1", "hint": "It is named after Nelson Mandela and describes shared false memories.", "answer": "The Mandela Effect"}], "points": 10, "prompt": "{{b1}} is a psychological phenomenon in which large numbers of people share the same false memory. It was named by paranormal researcher Fiona Broome after she and others wrongly recalled a world leader dying in prison in the 1980s. Examples include people recalling the Monopoly Man wearing a monocle, remembering a cornucopia in the Fruit of the Loom logo, and misquoting a famous Star Wars line as \"Luke, I am your father\" instead of \"No, I am your father.\" Identify X.", "feedback": {"correct": "Correct! This phenomenon is known as the Mandela Effect.", "incorrect": "Not quite. Think of the term for shared false memories."}, "question": "Identify X", "introLabel": "Text Blank", "attemptsAllowed": 2}, {"blanks": [{"id": "b1", "hint": "It is South Africa''s highest court for constitutional matters and is located at Constitution Hill.", "answer": "Constitutional Court of South Africa"}], "points": 10, "prompt": "Gandhi was jailed in 1908 in the same Johannesburg prison where Nelson Mandela was held 54 years later, in 1962. Its Section 4 now houses an exhibition on Gandhi, and a bust of him was unveiled nearby in 2012. In the mid-1990s, the Awaiting Trial Block where Mandela was held was demolished to make way for {{b1}}, which was built using the block''s original bricks. It is now South Africa''s highest court on matters of constitutional law. Identify X.", "feedback": {"correct": "Correct! The answer is the Constitutional Court of South Africa.", "incorrect": "Not quite. Think of South Africa''s highest constitutional court."}, "question": "Identify X", "introLabel": "Text Blank", "attemptsAllowed": 2}, {"blanks": [{"id": "b1", "hint": "It is a slang term for an improvised prison weapon.", "answer": "Shank"}], "points": 10, "prompt": "{{b1}} is an improvised stabbing weapon in American prison slang, often made by melting a razor blade into the end of a toothbrush or by filing down a metal bucket handle. Its name comes from a steel support rib once found in men''s boots and work boots, which 19th-century prisoners extracted and sharpened. In 1882, authorities holding Charles Guiteau confiscated his shoes for this very reason, though the slang then was \"cheeser.\" Its British counterpart derives its name from the Romani word for blade. Identify X.", "feedback": {"correct": "Correct! The answer is a shank.", "incorrect": "Not quite. Think of the prison slang term for an improvised stabbing weapon."}, "question": "Identify X", "introLabel": "Text Blank", "attemptsAllowed": 2}]', 1, 'cmvnt1dzz000207l801wbymza', NULL, NULL, '2026-10-25 12:29:18.239', '2026-10-25 12:29:18.239');
INSERT INTO public.game (id, type, title, subtitle, "isPremium", "subStages", "schemaVersion", "importBatchId", "editionId", "position", "createdAt", "updatedAt") VALUES ('cmvnt1hcw000507l84zx6del8', 'clue-connect', 'Clue Board', NULL, false, '[{"cases": [{"id": "marie-curie", "fact": "She was the first person to win Nobel Prizes in two different scientific fields.", "clues": [{"id": "curie-polonium-radium", "text": "Discovered polonium and radium", "isCorrect": true}, {"id": "curie-two-nobels", "text": "Won Nobel Prizes in Physics and Chemistry", "isCorrect": true}, {"id": "curie-radioactivity", "text": "Pioneered radioactivity research", "isCorrect": true}, {"id": "curie-radiation", "text": "Illness was linked to radiation exposure", "isCorrect": true}, {"id": "curie-light-bulb", "text": "Invented the light bulb", "isCorrect": false}, {"id": "curie-first-space", "text": "Was the first woman in space", "isCorrect": false}], "answer": "Marie Curie", "category": "History", "clueSlots": [{"x": 18, "y": 19}, {"x": 82, "y": 18}, {"x": 15, "y": 50}, {"x": 85, "y": 53}, {"x": 23, "y": 83}, {"x": 78, "y": 84}]}, {"id": "japan", "fact": "Japan is an island nation in the Pacific with Tokyo as its capital.", "clues": [{"id": "japan-islands", "text": "Made up of thousands of Pacific islands", "isCorrect": true}, {"id": "japan-fuji", "text": "Home to Mount Fuji", "isCorrect": true}, {"id": "japan-tokyo", "text": "Its capital is Tokyo", "isCorrect": true}, {"id": "japan-yen", "text": "Uses the yen as currency", "isCorrect": true}, {"id": "japan-china-border", "text": "Shares a land border with China", "isCorrect": false}, {"id": "japan-seoul", "text": "Its capital is Seoul", "isCorrect": false}], "answer": "Japan", "category": "Geography", "clueSlots": [{"x": 18, "y": 19}, {"x": 82, "y": 18}, {"x": 15, "y": 50}, {"x": 85, "y": 53}, {"x": 23, "y": 83}, {"x": 78, "y": 84}]}], "points": 150, "prompt": "Drag a string from the mystery card to each clue that truly belongs. Tap clues if you prefer.", "feedback": {"correct": "Every clue is connected. The board is solved.", "incorrect": "Too many decoys were connected. Look for clues that all point to the same answer."}, "question": "Connect the Clues", "introLabel": "Clue Board", "maxMistakes": 3, "attemptsAllowed": 1}]', 1, 'cmvnt1hch000407l8gg0za54m', NULL, NULL, '2026-10-25 12:29:22.577', '2026-10-25 12:29:22.577');
INSERT INTO public.game (id, type, title, subtitle, "isPremium", "subStages", "schemaVersion", "importBatchId", "editionId", "position", "createdAt", "updatedAt") VALUES ('cmvnt22g7000b07l8d47hun29', 'border-hop', 'Border Hop', 'Find a path across land borders.', false, '[{"points": 100, "question": "Cross Europe one border at a time.", "maxGuesses": 7, "hintsAllowed": 3, "startCountry": "Portugal", "targetCountry": "Germany", "attemptsAllowed": 3}, {"points": 100, "question": "Find your way across South America.", "maxGuesses": 6, "hintsAllowed": 3, "startCountry": "Colombia", "targetCountry": "Chile", "attemptsAllowed": 3}]', 1, 'cmvnt22ft000a07l8fcjbsukl', NULL, NULL, '2026-10-25 12:29:49.913', '2026-10-25 12:29:49.913');
